-- SOLIDATA | Registros base y datos de prueba PostgreSQL
-- Ejecutar despues de esqueleto.sql. Los INSERT son reejecutables con ON CONFLICT DO NOTHING.
-- Incluye el administrador inicial admin@example.invalid con contrasena 123.
BEGIN;
SET LOCAL search_path = public;
-- Instituciones ficticias para probar los marcadores del mapa en CABA.
ON CONFLICT DO NOTHING;
SELECT setval('public."Actions_id_seq"', (SELECT MAX(id) FROM public."Actions"), true);
SELECT setval('public."Articles_id_seq"', (SELECT MAX(id) FROM public."Articles"), true);
SELECT setval('public."DonationItems_id_seq"', (SELECT MAX(id) FROM public."DonationItems"), true);
SELECT setval('public."Donations_id_seq"', (SELECT MAX(id) FROM public."Donations"), true);
SELECT setval('public."Entities_id_seq"', (SELECT MAX(id) FROM public."Entities"), true);
SELECT setval('public."Institutions_id_seq"', (SELECT MAX(id) FROM public."Institutions"), true);
SELECT setval('public."InstitutionsNeeds_id_seq"', (SELECT MAX(id) FROM public."InstitutionsNeeds"), true);
SELECT setval('public."Inventories_id_seq"', (SELECT MAX(id) FROM public."Inventories"), true);
SELECT setval('public."Permissions_id_seq"', (SELECT MAX(id) FROM public."Permissions"), true);
SELECT setval('public."Roles_id_seq"', (SELECT MAX(id) FROM public."Roles"), true);
SELECT setval('public."Types_id_seq"', (SELECT MAX(id) FROM public."Types"), true);
SELECT setval('public."Users_id_seq"', (SELECT MAX(id) FROM public."Users"), true);
COMMIT;

